package local.zfttests;
import android.app.*;import android.content.*;import android.os.Bundle;import android.webkit.WebView;import android.view.View;import java.util.concurrent.*;import java.lang.reflect.*;import org.json.*;
public class Stocks extends Instrumentation {
 private Activity activity;private WebView web;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 private String eval(String code)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] result={null};runOnMainSync(()->web.evaluateJavascript(code,v->{result[0]=v;done.countDown();}));require(done.await(5,TimeUnit.SECONDS),"JS callback");return result[0];}
 private void until(String code,long timeout)throws Exception{long end=System.currentTimeMillis()+timeout;while(System.currentTimeMillis()<end){if("true".equals(eval(code)))return;Thread.sleep(500);}throw new AssertionError("Timed out: "+code+" page="+eval("document.body.innerText.slice(0,2000)"));}
 public void onStart(){Bundle out=new Bundle();try{
 getTargetContext().getSharedPreferences("local.zft.stocks.",0).edit().remove("watchlist").commit();
 activity=startActivitySync(new Intent().setClassName(getTargetContext(),"local.zft.StockActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
 runOnMainSync(()->{web=activity.getWindow().getDecorView().findViewWithTag("local.zft.stocks");require(web!=null&&web.getVisibility()==View.VISIBLE,"stocks page visible");require(activity.getWindow().getDecorView().findViewWithTag("local.zft.tab.3").isSelected(),"bottom stocks tab selected");});
 until("typeof window.stockActive==='function'",15000);
 Class<?> panel=getTargetContext().getClassLoader().loadClass("local.zft.StockPanel");Method allowed=panel.getDeclaredMethod("allowed",java.net.URI.class);allowed.setAccessible(true);require(!(Boolean)allowed.invoke(null,new java.net.URI("https://evil.example/api")),"external host blocked");require(!(Boolean)allowed.invoke(null,new java.net.URI("http://web.ifzq.gtimg.cn/appstock/app/minute/query")),"HTTP blocked");
 require("true".equals(eval("document.getElementById('search-panel').hidden")),"search collapsed by default");runOnMainSync(()->activity.getWindow().getDecorView().findViewWithTag("local.zft.stock-search").performClick());until("document.getElementById('search-panel').open && document.getElementById('search-panel').matches(':modal')",5000);capture("stocks-search-modal.png");eval("document.getElementById('query').value='603629';document.getElementById('search').requestSubmit()");until("document.querySelectorAll('.result').length>0",30000);out.putString("search",eval("document.getElementById('search-status').textContent"));
 eval("document.querySelector('.result').click()");until("document.querySelector('.stock-row .price')!==null && document.querySelector('.stock-row .price').textContent!=='—'",70000);require("true".equals(eval("document.querySelectorAll('.result').length===0 && document.getElementById('query').value==='' && document.getElementById('search-panel').hidden")),"adding stock dismisses search results and clears input");require(!"\"—\"".equals(eval("document.querySelector('.price').textContent")),"live quote available");out.putString("source",eval("Array.from(document.querySelectorAll('.stock-row .meta')).map(x=>x.textContent).join(' | ')"));
 require("true".equals(eval("document.querySelectorAll('#cards canvas').length===0 && document.querySelector('.stock-open').getBoundingClientRect().height<100")),"compact watchlist has no inline charts");runOnMainSync(()->callActivityOnPause(activity));require("false".equals(eval("document.getElementById('refresh').disabled")),"pause releases refresh button");runOnMainSync(()->callActivityOnResume(activity));
 eval("document.querySelector('.name').click();document.getElementById('daily').click()");until("document.getElementById('detail').open && document.querySelector('.chart.daily')!==null",5000);
 require("true".equals(eval("document.querySelector('.detail-price')!==null && document.querySelector('.ma-legend').textContent.includes('MA20')")),"quote-first detail and original MA legend");out.putString("detail",eval("document.querySelector('.data-notes').textContent"));capture("stocks-daily-preview.png");runOnMainSync(()->{try{Field f=activity.getClass().getDeclaredField("systemBack");f.setAccessible(true);((android.window.OnBackInvokedCallback)f.get(activity)).onBackInvoked();}catch(Exception e){throw new RuntimeException(e);}});until("!document.getElementById('detail').open",5000);eval("document.querySelector('.name').click()");capture("stocks-minute-preview.png");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);until("!document.getElementById('detail').open",5000);require(!activity.isFinishing(),"Android back closes detail without leaving watchlist");capture("stocks-preview.png");
 require(eval("StockStorage.read()").contains("603629"),"watchlist persisted");eval("document.getElementById('manage').click();document.querySelector('.remove').click()");require("\"[]\"".equals(eval("StockStorage.read()")),"remove persisted");ActivityMonitor monitor=addMonitor("com.zhongfutong.main.MainTabActivity",null,false);runOnMainSync(()->activity.getWindow().getDecorView().findViewWithTag("local.zft.tab.2").performClick());Activity main=waitForMonitorWithTimeout(monitor,5000);require(main!=null,"stocks to mine navigation");waitForIdleSync();require(main.getClass().getField("x4").getInt(main)==4,"stocks routes original mine index");removeMonitor(monitor);out.putString("result","PASS: real Android WebView search, live quote, sources, intraday/day charts, detail, tab switch, local add/remove and host restriction");finish(-1,out);
 }catch(Throwable e){out.putString("result","FAIL: "+e);finish(0,out);}}
 private void capture(String name)throws Exception{Thread.sleep(700);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),name))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
}
